fn publish_metrics(&self) {
    let snap = self.snapshot();
    metrics::ACTION_CONTROL_LOADED.set(i64::from(snap.loaded_at.is_some()));
    for mode in [
        ControlMode::Rules,
        ControlMode::Recording,
